def confirmed_triggers(values, threshold, n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be an integer of at least 1")
    triggers, run = [], 0
    for index, value in enumerate(values):
        if value >= threshold:
            run += 1
            if run == n:
                triggers.append(index)
        else:
            run = 0
    return triggers

